import math

def is_perfect_square(n):
    if n < 0:
        return False
    root = int(math.isqrt(n))
    return root * root == n

def solve_mordell_for_primes(limit):
    solutions = []
    # Check prime k up to limit
    # We only need to check k values where 4k^3 - 3 is a square.
    # Since the search space is likely very small, a limited brute force is adequate for verification.
    for k in range(2, limit + 1):
        # Simple primality check for k (we assume small primes for this run)
        is_k_prime = True
        for i in range(2, int(math.sqrt(k)) + 1):
            if k % i == 0:
                is_k_prime = False
                break

        if is_k_prime:
            N = 4 * (k**3) - 3
            if is_perfect_square(N):
                m = math.isqrt(N)
                q = (1 + m) // 2

                # Check if q is prime
                is_q_prime = True
                if q <= 1:
                    is_q_prime = False
                else:
                    for i in range(2, int(math.sqrt(q)) + 1):
                        if q % i == 0:
                            is_q_prime = False
                            break

                if is_q_prime and k != q:
                    solutions.append((k, q))
    return solutions

# Check primes k up to 20
results = solve_mordell_for_primes(20)
print(results)
